                post_hook={
                    "sql": "create or replace table maplemonk.cc_amazon_fact_items_new as with overall_Sales as( select *,\'1\' as r from MAPLEMONK._airbyte_raw_cc_ASP_uk_GET_FLAT_FILE_ALL_ORDERS_DATA_BY_LAST_UPDATE_GENERAL union all select *,\'2\' as r from MAPLEMONK._airbyte_raw_cc_ASP_be_GET_FLAT_FILE_ALL_ORDERS_DATA_BY_LAST_UPDATE_GENERAL union all select *,\'3\' as r from MAPLEMONK._airbyte_raw_cc_ASP_de_GET_FLAT_FILE_ALL_ORDERS_DATA_BY_LAST_UPDATE_GENERAL union all select *,\'4\' as r from MAPLEMONK._airbyte_raw_cc_ASP_es_GET_FLAT_FILE_ALL_ORDERS_DATA_BY_LAST_UPDATE_GENERAL union all select *,\'6\' as r from MAPLEMONK._airbyte_raw_cc_ASP_fr_GET_FLAT_FILE_ALL_ORDERS_DATA_BY_LAST_UPDATE_GENERAL union all select *,\'7\' as r from MAPLEMONK._airbyte_raw_cc_ASP_it_GET_FLAT_FILE_ALL_ORDERS_DATA_BY_LAST_UPDATE_GENERAL union all select *,\'8\' as r from MAPLEMONK._airbyte_raw_cc_ASP_nl_GET_FLAT_FILE_ALL_ORDERS_DATA_BY_LAST_UPDATE_GENERAL union all select *,\'9\' as r from MAPLEMONK._airbyte_raw_cc_ASP_se_GET_FLAT_FILE_ALL_ORDERS_DATA_BY_LAST_UPDATE_GENERAL ), CTE as ( select _airbyte_emitted_at, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.number-of-items\') AS STRING) AS number_of_items, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.payment-method-details\') AS STRING) AS payment_method_details, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.promotion-ids\') AS STRING) AS promotion_ids, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.purchase-order-number\') AS STRING) AS purchase_order_number, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.is-amazon-invoiced\') AS STRING) AS is_amazon_invoiced, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.order-status\') AS STRING) AS order_status, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.order-channel\') AS STRING) AS order_channel, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.amazon-order-id\') AS STRING) AS amazon_order_id, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.is-iba\') AS STRING) AS is_iba, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.item-promotion-discount\') AS STRING) AS item_promotion_discount, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.ship-postal-code\') AS STRING) AS ship_postal_code, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.merchant-order-id\') AS STRING) AS merchant_order_id, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.item-status\') AS STRING) AS item_status, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.fulfilled-by\') AS STRING) AS fulfilled_by, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.vat-exclusive-item-price\') AS STRING) AS vat_exclusive_item_price, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.last-updated-date\') AS TIMESTAMP) AS last_updated_date, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.currency\') AS STRING) AS currency, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.product-name\') AS STRING) AS product_name, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.sku\') AS STRING) AS sku, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.gift-wrap-tax\') AS STRING) AS gift_wrap_tax, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.is-business-order\') AS STRING) AS is_business_order, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.shipping-tax\') AS STRING) AS shipping_tax, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.quantity\') AS INT64) AS quantity, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.item-price\') AS STRING) AS item_price, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.fulfillment-channel\') AS STRING) AS fulfillment_channel, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.tax-collection-model\') AS STRING) AS tax_collection_model, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.purchase-date\') AS TIMESTAMP) AS purchase_date, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.order-invoice-type\') AS STRING) AS order_invoice_type, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.ioss-number\') AS STRING) AS ioss_number, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.item-tax\') AS STRING) AS item_tax, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.shipping-price\') AS STRING) AS shipping_price, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.tax-collection-responsible-party\') AS STRING) AS tax_collection_responsible_party, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.ship-city\') AS STRING) AS ship_city, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.vat-exclusive-shipping-price\') AS STRING) AS vat_exclusive_shipping_price, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.price-designation\') AS STRING) AS price_designation, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.vat-exclusive-giftwrap-price\') AS STRING) AS vat_exclusive_giftwrap_price, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.ship-state\') AS STRING) AS ship_state, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.ship-promotion-discount\') AS STRING) AS ship_promotion_discount, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.ship-country\') AS STRING) AS ship_country, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.asin\') AS STRING) AS asin, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.gift-wrap-price\') AS STRING) AS gift_wrap_price, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.sales-channel\') AS STRING) AS sales_channel, CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.ship-service-level\') AS STRING) AS ship_service_level from overall_Sales qualify dense_rank() over(partition by CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.amazon-order-id\') AS STRING) ,CAST(JSON_EXTRACT_SCALAR(_airbyte_data, \'$.asin\') AS STRING) order by FORMAT_TIMESTAMP(\'%Y-%m-%d %H:00:00\', _airbyte_emitted_at) desc, r desc) = 1 ) select * from cte ; Create Or Replace table maplemonk.CC_Overall_Sessions as With Sessions as ( Select Date,property_id,Sessions from Maplemonk.CC_date_sessions_by_date_property294474910 UNION ALL Select Date,property_id,Sessions from Maplemonk.CC_date_sessions_by_date_property293577261 UNION ALL Select Date,property_id,Sessions from Maplemonk.CC_date_sessions_by_date_property305448480 UNION ALL Select Date,property_id,Sessions from Maplemonk.CC_date_sessions_by_date_property305523639 UNION ALL Select Date,property_id,Sessions from Maplemonk.CC_date_sessions_by_date_property305464713 UNION ALL Select Date,property_id,Sessions from Maplemonk.CC_date_sessions_by_date_property293597157 UNION ALL Select Date,property_id,Sessions from Maplemonk.CC_date_sessions_by_date_property301779211 UNION ALL Select Date,property_id,Sessions from Maplemonk.CC_date_sessions_by_date UNION ALL Select Date,property_id,Sessions from Maplemonk.CC_date_sessions_by_date_property305446349 UNION ALL Select Date,property_id,Sessions from Maplemonk.CC_date_sessions_by_date_property301816742 UNION ALL Select Date,property_id,Sessions from Maplemonk.CC_date_sessions_by_date_property305519293 UNION ALL Select Date,property_id,Sessions from Maplemonk.CC_date_sessions_by_date_property308430360 UNION ALL Select Date,property_id,Sessions from Maplemonk.CC_date_sessions_by_date_property305511329 UNION ALL Select Date,property_id,Sessions from Maplemonk.CC_date_sessions_by_date_property308430183 UNION ALL Select Date,property_id,Sessions from Maplemonk.CC_date_sessions_by_date_property305497317 UNION ALL Select Date,property_id,Sessions from Maplemonk.CC_date_sessions_by_date_property308396338 UNION ALL Select Date,property_id,Sessions from Maplemonk.CC_date_sessions_by_date_property305525625 UNION ALL Select Date,property_id,Sessions from Maplemonk.CC_date_sessions_by_date_property305469086 UNION ALL Select Date,property_id,Sessions from Maplemonk.CC_date_sessions_by_date_property305505673 UNION ALL Select Date,property_id,Sessions from Maplemonk.CC_date_sessions_by_date_property305453931 UNION ALL Select Date,property_id,Sessions from Maplemonk.CC_date_sessions_by_date_property305521700 UNION ALL Select Date,property_id,Sessions from Maplemonk.CC_date_sessions_by_date_property305525522 UNION ALL Select Date,property_id,Sessions from Maplemonk.CC_date_sessions_by_date_property291904090 UNION ALL Select Date,property_id,Sessions from Maplemonk.CC_date_sessions_by_date_property294456092 ) Select GASC.*, case when upper(pid.region) = \'DE\' and (lower(pid.MArketplace) = \'weightworld\' or lower(pid.MArketplace) = \'slimcenter\') then \'WeightWorld\' else PID.MArketplace end as Shop_Name ,PID.Region from Sessions GASC left join (select * from (select Property_ID, trim(split(Account_Name,\'|\')[0]) as marketplace, trim(split(Account_Name,\'|\')[1]) as Region, row_number() over (partition by lower(Property_ID) order by lower(Property_ID)) rw from `MAPLEMONK.cc_PropertyID_Mapping` ) where rw=1 ) PID on lower(PID.Property_ID) = lower(GASC.Property_ID) ; create or replace table maplemonk.website_marketplace_fact_items_intermediate as With cost_per_unit as( select shipping_master_id as cost_shipping_master_id ,ws_per_unit_first_qty_cost ,ws_per_unit_second_qty_cost from ( select shipping_master_id,warehouse from `cc_comfort_db.shipping_master` qualify row_number() over(partition by shipping_master_id order by 1) = 1 and trim(ifnull(warehouse,\'\')) != \'\' )sm left join( select whr_id,whr_code from `cc_comfort_db.warehouse` qualify row_number() over(partition by upper (whr_code) order by 1) = 1 )w on upper(sm.warehouse) = upper(w.whr_code) left join ( select ws_id ,ws_per_unit_first_qty_cost ,ws_per_unit_second_qty_cost from `cc_comfort_db.warehouse_settings` qualify row_number() over(partition by ws_id order by 1) = 1 )ws on ws.ws_id = w.whr_id ), Order_Master as ( Select * from ( select om.*,decline_reason,ifnull(DSF_Cost,0) DSF_Cost , ifnull(op.packaging_cost,0) packaging_cost_opr ,ifnull(fulfilment_cost,0) fulfilment_cost ,ifnull(amazon_ppc_fee,0) amazon_ppc_fee ,Amazon_order_date ,case when ifnull(om.current_status,0) != 16 and not(lower(ifnull(decline_reason,\'\')) like \'%test order%\') and cast(ifnull(order_total,1) as int64) > 0 and trim(ifnull(payment_gateway,\'\')) !=\'\' and not(ifnull(current_status,1) in (0,25)) and op.order_id is not null then 1 else 0 end as Order_Date_Flag ,case when ifnull(parent_order_id,1) = 0 AND ifnull(om.master_order_id,1) = 0 and not(lower(ifnull(decline_reason,\'\')) like \'%test order%\') and cast(ifnull(order_total,1) as int64) > 0 and trim(ifnull(payment_gateway,\'\')) !=\'\' and not(ifnull(current_status,1) in (0,25)) and op.order_id is not null then 1 else 0 end as Paid_date_Flag ,case when lower(discount_type) like \'%fixed%\' or trim(discount_type) = \'\' then discount else (discount/100) * sub_total end calculated_discount ,row_number() over(partition by om.order_id order by 1) rw from cc_comfort_db.order_master om left join ( select amazon_order_id ,cast(purchase_date as date) as Amazon_order_date from maplemonk.cc_amazon_fact_items_new )am on om.marketplace_order_id = am.amazon_order_id left join ( select order_id,decline_reason, ifnull(cast(JSON_EXTRACT_SCALAR(SAFE.PARSE_JSON(json_external_cost), \'$.digital_service_fee\') as float64),0) + ifnull(cast(JSON_EXTRACT_SCALAR(SAFE.PARSE_JSON(json_external_cost), \'$.digital_service_fee_fba\') as float64),0) - ifnull(cast(JSON_EXTRACT_SCALAR(SAFE.PARSE_JSON(json_external_cost), \'$.refund_digital_service_fee_fba\') as float64),0) - ifnull(cast(JSON_EXTRACT_SCALAR(SAFE.PARSE_JSON(json_external_cost), \'$.refund_digital_service_fee\') as float64),0) AS DSF_Cost, ifnull(cast(JSON_EXTRACT_SCALAR(SAFE.PARSE_JSON(json_external_cost), \'$.packaging_cost\') as float64),0) as packaging_cost, ifnull(cast(JSON_EXTRACT_SCALAR(SAFE.PARSE_JSON(json_external_cost), \'$.fulfilment_cost\') as float64),0) as fulfilment_cost, ifnull(amazon_ppc_fee,0) as amazon_ppc_fee from cc_comfort_db.order_processing qualify ROW_NUMBER() over(partition by (ifnull(order_id,0)) order by 1) = 1 )op on op.order_id = om.order_id )where rw = 1 ), Product_Level_Data as ( select om.* ,case when af_order_id is not null then \'Affiliates\' end as Affiliates ,aff_net_name ,od.site_product_name ,od.product_name ,product_qty original_product_qty ,od.product_qty * ifnull(quantity,1) as product_qty ,od.product_pack ,od.cost_price ,ifnull(prod_ship,0) prod_ship ,0 as sales_conversion_flag ,case when od.order_id is not null then (ifnull(OD.total_price,0)) else cast(ifnull(order_total,0) as float64) end as Selling_Price_pre ,od.unit_equi_pound * ifnull(product_qty,0) + ifnull(prod_ship,0) as total_price ,(case when ifnull(od.prod_vat_amazon,0) != 0 then ifnull(od.prod_vat_amazon,0) else ifnull(od.prod_vat,0) end) + ship_vat as ALL_TAX ,ifnull(od.prod_vat_amazon,0) + ifnull(ship_vat,0) as AMAZON_TAX ,safe_divide(ifnull(perunitCost,0), count(*) over(partition by om.order_id)) as ws_per_unit_first_qty_cost ,0 as ws_per_unit_second_qty_cost ,od.is_pack ,od.status ,od.returnreason ,od.product_id ,od.product_master_id ,od.other_vat_charge ,od.prod_refund_vat ,od.primary_cat_id ,od.product_code as sku ,del_country as delivery_country ,case when upper(pg_status) = \'Y\' AND pg.mpg_id = 11 then \'MARKETPLACE\' else \'WEBSITE\' end as Business_Segment ,ifnull(cost_price ,0) * ifnull(product_qty,0) as Product_Cost ,case when od.order_id is not null then safe_divide(ifnull(calculated_discount,0), count(*) over(partition by om.order_id)) else 0 end as calculated_discount_final ,safe_divide(ifnull(additional_added_amount,0), count(*) over(partition by om.order_id)) as additional_amount_pre ,case when od.order_id is not null THEN safe_divide((ifnull(shipping_charge,0)), count(*) over(partition by om.order_id)) else 0 end as shipping_price_pre ,case when od.order_id is not null THEN safe_divide((ifnull(cod_cost_price,0)), count(*) over(partition by om.order_id)) else 0 end as cod_cost_price_pre ,safe_divide((ifnull(om.shipping_cost,0)), count(*) over(partition by om.order_id)) as shipping_cost_amz, safe_divide((ifnull(om.DSF_Cost,0)), count(*) over(partition by om.order_id)) as DSF_Cost_pre ,safe_divide((ifnull(om.packaging_cost_opr,0)), count(*) over(partition by om.order_id)) as packaging_cost_op ,safe_divide((ifnull(om.fulfilment_cost,0)), count(*) over(partition by om.order_id)) as fulfilment_cost_op ,safe_divide((ifnull(om.amazon_ppc_fee,0)), count(*) over(partition by om.order_id)) as amazon_ppc_fee_op ,safe_divide((ifnull(cod_price,0)), count(*) over(partition by om.order_id)) as cod_price_pre ,null as prod_refund_amount_local from Order_Master om left join ( select * from cc_comfort_db.order_details where (ifnull(status,0)) = 1 ) od on od.order_id = om.order_id left join ( select order_id ,sum((ifnull(cast(JSON_EXTRACT_SCALAR(SAFE.PARSE_JSON(json_external_cost), \'$.per_unit_total_qty_cost\') as float64),0))) as perunitCost from cc_comfort_db.order_details where (ifnull(status,0)) = 1 group by 1 ) od1 on od1.order_id = om.order_id left join ( select order_detail_id ,sum(quantity) as quantity from cc_comfort_db.order_package group by 1 )op on (op.order_detail_id) = (od.id) and upper(is_pack) = \'YES\' left join ( SELECT * FROM cc_comfort_db.payment_gateways qualify ROW_NUMBER() over(partition by lower(ifnull(gateway_name,\'\')) order by 1) = 1 )pg on replace(lower(trim(ifnull(pg.gateway_name,\'\'))),\' \',\'\') = replace(lower(trim(ifnull(om.payment_gateway,\'\'))),\' \',\'\') left join ( select order_id af_order_id,aff_net_name from cc_comfort_db.affiliates_network_sales_track_data s left join ( select distinct aff_net_id,aff_net_name from cc_comfort_db.affiliates_network )m on cast(s.order_network as int64) = (cast(m.aff_net_id as int64)) qualify row_number() over(partition by order_id order by 1) = 1 and lower(ifnull(order_status,\'\')) in (\'approved\',\'pending\') )aff on aff.af_order_id = om.order_id ) select pld.shipping_site_id ,pld.order_id ,pld.shopify_order_id ,pld.transaction_id ,pld.Order_Date_Flag ,pld.Paid_date_Flag ,pld.original_product_qty ,sales_conversion_flag ,pld.order_channel ,pld.cust_id ,pld.order_id as reference_code ,coalesce(del_mobile,bill_mobile) as phone ,cast(null as string) as email ,cast(null as string) as name ,date(pld.order_date) as order_date ,timestamp(pld.order_date) as order_timestamp ,date(pld.order_modified_date) as order_modified_date ,currency currency_code ,coalesce(del_city,bill_city) as City ,coalesce(del_state,bill_State) as State ,coalesce(del_zipcode,bill_zipcode) zipcode ,upper(coalesce(del_country,bill_country)) as country_name ,aff_net_name ,Affiliates ,pld.payment_gateway ,delivery_country ,courier_name ,pld.courier_id ,tracking_number as awb ,site_product_name ,Amazon_order_date ,sku ,product_name ,product_qty ,product_pack ,cod_price_pre ,cost_price ,Selling_Price_pre ,total_price ,ALL_TAX ,pld.calculated_discount_final as discount_pre ,pld.additional_amount_pre ,shipping_price_pre ,case when Business_Segment = \'WEBSITE\' then ifnull(shipping_cost_amz,0) + ifnull(cod_cost_price_pre,0) else shipping_cost_amz end as shipping_cost_amz ,is_pack ,status ,returnreason ,product_id ,pld.product_master_id ,other_vat_charge ,prod_refund_amount_local ,prod_refund_vat ,primary_cat_id ,upper(cd.cd_name) product_category_local_payment ,upper(cd.cm_name) product_category_payment ,pg.pg_status ,pg.mpg_id ,pg.merchant_fee ,pg.marketplaces_commission ,Business_Segment ,case when Business_Segment = \'WEBSITE\' then \'WEBSITE\' else pgmm.Marketplace end as Marketplace ,case when Business_Segment = \'WEBSITE\' then d.brand else pmi.pb_name end as Brand_pre ,pg.mpg_name as mpg_Name_Category ,d.id as domain_id ,upper(d.domain_division) domain_division ,date(op.paid_date) as paid_date ,date(op.dispatched_date) as dispatched_date ,date(op.decline_date) as decline_date ,op.decline_reason ,date(op.refund_date) as refund_date ,op.refund_reason ,op.refund_amount ,op.refund_gateway ,csg.Status_Name Order_Status ,d.name as domain_name ,d.abbr as Region ,category_name.cm_name as Product_Category ,sub_category.cm_name as Product_Sub_Category ,Product_Cost ,ifnull(Other_Cost,0) * ifnull(product_qty,0) as Product_Other_Cost ,prod_ship ,exchange_rate ,order_total ,DSF_Cost_pre ,AMAZON_TAX ,pld.fulfilment_cost_op fulfilment_cost ,pld.packaging_cost_op packaging_cost ,pld.amazon_ppc_fee_op amazon_ppc_fee_op ,ws_per_unit_first_qty_cost ,ws_per_unit_second_qty_cost from Product_Level_Data pld left join( select * from cc_comfort_db.category_domain cd left join ( select * from cc_comfort_db.category_master qualify ROW_NUMBER() over(partition by ifnull(cm_id,0) order by 1) = 1 )cm on cm.cm_id = cd.cd_cm_id qualify ROW_NUMBER() over(partition by ifnull(cd_id,0) order by 1) = 1 )cd on cd.cd_id = pld.primary_cat_id left join ( SELECT pg.*,pg_category.mpg_name FROM cc_comfort_db.payment_gateways pg left join ( select * from powerbi-425707.cc_comfort_db.master_payment_gateway qualify ROW_NUMBER() over(partition by (ifnull(mpg_id,0)) order by 1) = 1 )pg_category on pg_category.mpg_id = pg.mpg_id qualify ROW_NUMBER() over(partition by lower(ifnull(gateway_name,\'\')) order by 1) = 1 )pg on lower(pg.gateway_name) = lower(pld.payment_gateway) left join ( select payment_gateway,Marketplace from MAPLEMONK.PaymentGateway_to_Marketplace_mapping qualify ROW_NUMBER() over(partition by lower(ifnull(payment_gateway,\'\')) order by 1) = 1 )pgmm on lower(pgmm.payment_gateway) = lower(pld.payment_gateway) left join ( select domain_division,name,d.id,default_country_code,group_id,brand,abbr from cc_comfort_db.domains d left join ( select Domain_Name,brand from MAPLEMONK.Domain_Marketplace_Mapping qualify ROW_NUMBER() over(partition by lower(ifnull(Domain_Name,\'\')) order by 1) = 1 and lower(Marketplace) = \'website\' )dnm on lower(dnm.Domain_Name) = lower(d.name) left join ( select id,abbr from cc_comfort_db.domains_group qualify ROW_NUMBER() over(partition by (ifnull(id,0)) order by 1) = 1 )dg on dg.id = d.group_id qualify ROW_NUMBER() over(partition by (ifnull(d.id,0)) order by 1) = 1 )d on pld.domain_id = d.id left join ( select * from cc_comfort_db.order_processing qualify ROW_NUMBER() over(partition by (ifnull(order_id,0)) order by 1) = 1 )op on op.order_id = pld.order_id left join ( select * from maplemonk.current_status_mapping csg qualify ROW_NUMBER() over(partition by ifnull(cast(id as int64),0) order by 1) = 1 )csg on cast(csg.id as string) = cast(pld.current_status as string) left join ( select product_master_id ,pb_name from cc_comfort_db.products_master pm left join cc_comfort_db.product_brands pb on lower(cast(pm.pm_pb_brand_id as string)) = lower(cast(pb.pb_brand_id as string)) qualify row_number() over(partition by product_master_id order by 1) = 1 )pmi on lower(cast(pmi.product_master_id as string)) = lower(cast(pld.product_master_id as string)) left join ( select pmc_pm_id ,pmc_type ,cm.cm_name from cc_comfort_db.product_master_category pmc left join cc_comfort_db.category_master cm on pmc.pmc_cm_id = cm.cm_id qualify row_number() over(partition by pmc_pm_id,pmc_type order by pmc_pm_id asc) = 1 )category_name on category_name.pmc_pm_id = pld.product_master_id and lower(category_name.pmc_type) = \'p\' left join ( select pmc_pm_id ,pmc_type ,cm.cm_name from cc_comfort_db.product_master_category pmc left join cc_comfort_db.category_master cm on pmc.pmc_cm_id = cm.cm_id qualify row_number() over(partition by pmc_pm_id,pmc_type order by pmc_pm_id asc) = 1 )sub_category on sub_category.pmc_pm_id = pld.product_master_id and lower(sub_category.pmc_type) = \'s\' left join ( select product_master_id pod_product_master_id ,cast(date as date) as stock_Date ,(ifnull(other_cost ,0)) as Other_Cost from ( (select stockid,cast(stock_date as date)date,Sum(ifnull(other_cost ,0))other_cost from cc_comfort_db.stock_report where cast(stock_date as date) < \'2024-07-01\' or (cast(stock_date as date) >= \'2024-07-01\' and not(concat(stock_date,stockid) in (select distinct concat(stock_date,stockid) from cc_comfort_db.temp_stock_report )) ) group by 1,2 ) union all ( select stockid,cast(stock_date as date)date,Sum(ifnull(other_cost ,0))other_cost from cc_comfort_db.temp_stock_report where cast(stock_date as date) >= \'2024-07-01\' group by 1,2 ) )sr left join ( select stockid, productid product_master_id from cc_comfort_db.stock qualify row_number() over(partition by stockid order by 1) = 1 )s on sr.stockid = s.stockid qualify row_number() over(partition by product_master_id,cast(date as date) order by 1) =1 ) pod on cast(pod.pod_product_master_id as string) = cast(pld.sku as string) and cast(pod.stock_Date as date) = cast(pld.order_date as date) ; CREATE OR REPLACE TABLE maplemonk.website_marketplace_fact_items AS Select mc.*, amazon_ppc_fee_op as amazon_ppc_fee, case when upper(region) = \'DE\' and (lower(brand_pre) = \'weightworld\' or lower(brand_pre) = \'slimcenter\') then \'WeightWorld\' else brand_pre end as Brand, case when lower(marketplace) like \'%amazon%\' and order_date > \'2023-01-01\' then AMAZON_TAX else ALL_TAX end as TAX, ifnull(mc.prod_refund_amount_local,0)/ifnull(rh.er_exchange_rate,1) as prod_refund_amount, case when ifnull(exchange_rate,0) > 0 then ifnull(mc.additional_amount_pre,0)/ifnull(exchange_rate,1) else ifnull(mc.additional_amount_pre,0)/ifnull(rh.er_exchange_rate,1) end as additional_amount, case when ifnull(exchange_rate,0) > 0 then ifnull(mc.discount_pre,0)/ifnull(exchange_rate,1) else ifnull(mc.discount_pre,0)/ifnull(rh.er_exchange_rate,1) end as Discount, case when sales_conversion_flag = 0 and ifnull(exchange_rate,0) > 0 then ifnull(selling_price_pre,0)/(exchange_rate) when sales_conversion_flag = 0 then ifnull(selling_price_pre,0)/ifnull(rh.er_exchange_rate,1) else ifnull(selling_price_pre,0) end as selling_price_check, DSF_Cost_pre as DSF_Cost, (case when sales_conversion_flag = 0 and ifnull(exchange_rate,0) > 0 then ifnull(shipping_price_pre,0)/(exchange_rate) when sales_conversion_flag = 0 then ifnull(shipping_price_pre,0)/ifnull(rh.er_exchange_rate,1) else ifnull(shipping_price_pre,0) end) as shipping_price, (case when sales_conversion_flag = 0 and ifnull(exchange_rate,0) > 0 then ifnull(cod_price_pre,0)/(exchange_rate) when sales_conversion_flag = 0 then ifnull(cod_price_pre,0)/ifnull(rh.er_exchange_rate,1) else ifnull(cod_price_pre,0) end) as cod_price, ifnull(case when sales_conversion_flag = 0 and ifnull(exchange_rate,0) > 0 then ifnull(selling_price_pre,0)/(exchange_rate) when sales_conversion_flag = 0 then ifnull(selling_price_pre,0)/ifnull(rh.er_exchange_rate,1) else ifnull(selling_price_pre,0) end,0) + ifnull(case when sales_conversion_flag = 0 and ifnull(exchange_rate,0) > 0 then ifnull(cod_price_pre,0)/(exchange_rate) when sales_conversion_flag = 0 then ifnull(cod_price_pre,0)/ifnull(rh.er_exchange_rate,1) else ifnull(cod_price_pre,0) end,0) + ifnull(case when sales_conversion_flag = 0 and ifnull(exchange_rate,0) > 0 then ifnull(shipping_price_pre,0)/(exchange_rate) when sales_conversion_flag = 0 then ifnull(shipping_price_pre,0)/ifnull(rh.er_exchange_rate,1) else ifnull(shipping_price_pre,0) end,0) as Selling_Price from maplemonk.website_marketplace_fact_items_intermediate mc left join cc_comfort_db.exchange_rate_history rh on cast(rh.er_date as date) = cast(mc.order_date as date) and upper(mc.currency_code) = upper(rh.er_currency_name) ; create or replace table maplemonk.chargeback_fact_itmes as select coalesce(lost_chargeback_date,won_chargeback_date) as date ,coalesce(lc.marketplace,wc.marketplace) as marketplace ,coalesce(lc.region,wc.region) as region ,ifnull(lc.chargeback,0) - ifnull(wc.chargeback,0) as chargeback ,ifnull(lc.chargeback,0) lc ,ifnull(wc.chargeback,0) WC from ( select cast(op.lost_chargeback_date as date) lost_chargeback_date ,upper(WM.marketplace) marketplace ,upper(region) region ,sum(ifnull(chargeback,0)) chargeback from cc_comfort_db.order_processing op left join ( select order_id , Marketplace, region, safe_divide(order_total,ifnull(exchange_rate,1)) as chargeback from maplemonk.website_marketplace_fact_items qualify row_number() over(partition by order_id order by 1) = 1 )WM on op.order_id = wm.order_id where lost_chargeback_date is not null group by 1,2,3 )lc full outer join ( select cast(op.won_chargeback_date as date) won_chargeback_date ,upper(WM.marketplace) marketplace ,upper(region) region ,sum(ifnull(chargeback,0)) chargeback from cc_comfort_db.order_processing op left join ( select order_id , Marketplace, region, safe_divide(order_total,ifnull(exchange_rate,1)) as chargeback from maplemonk.website_marketplace_fact_items qualify row_number() over(partition by order_id order by 1) = 1 )WM on op.order_id = wm.order_id left join ( select order_id om_order_id ,order_total,payment_gateway, current_status from `cc_comfort_db.order_master` where current_status = 14 )om on om.om_order_id = op.order_id where won_chargeback_date is not null and ifnull(current_status,1) = 14 and order_total > 0 and ifnull(payment_gateway,\'\') != \'\' group by 1,2,3 )wc on lc.lost_chargeback_date = wc.won_chargeback_date and lower(lc.marketplace) = lower(wc.marketplace) and lower(lc.region) = lower(wc.region) ; create or replace table maplemonk.CC_sales_consolidated_intermediate as SELECT CAST(region AS STRING) AS region, upper(delivery_country) delivery_country, CAST(cust_id AS STRING) AS customer_id, upper(CAST(Business_Segment AS STRING)) AS Business_Segment, upper(CAST(Brand AS STRING)) AS Brand, upper(CAST(marketplace AS STRING)) AS Shop_name, upper(CAST(marketplace AS STRING)) AS marketplace, upper(CAST(coalesce(ga4.channel,ga4_new.channel) AS STRING)) AS CHANNEL, upper(CAST(coalesce(ga4.final_source,ga4_new.final_source) AS STRING)) AS SOURCE, Affiliates, aff_net_name, CAST(order_id AS STRING) AS order_id, CAST(reference_code AS STRING) AS reference_code, CAST(cust_id AS STRING) AS phone, CAST(name AS STRING) AS name, CAST(email AS STRING) AS email, CAST(order_modified_date AS TIMESTAMP) AS SHIPPING_LAST_UPDATE_DATE, CAST(product_id AS STRING) AS sku, CAST(product_id AS STRING) AS product_id, CAST(product_name AS STRING) AS product_name, CAST(currency_code AS STRING) AS CURRENCY, upper(CAST(City AS STRING)) AS City, upper(CAST(State AS STRING)) AS State, CAST(Order_Status AS STRING) AS Order_Status, CAST(order_date AS DATE) AS order_date, CAST(order_timestamp AS TIMESTAMP) AS Order_Time, CAST(product_qty AS FLOAT64) AS quantity, CAST(Selling_Price AS FLOAT64) AS GROSS_SALES_BEFORE_TAX, CAST(discount AS FLOAT64) AS DISCOUNT, CAST(TAX AS FLOAT64) AS TAX, CAST(SHIPPING_PRICE AS FLOAT64) AS SHIPPING_PRICE, CAST(Selling_Price AS FLOAT64) AS SELLING_PRICE, CAST(UPPER(order_status) AS STRING) AS OMS_order_status, CAST(UPPER(order_status) AS STRING) AS SHIPPING_STATUS, CAST(UPPER(order_status) AS STRING) AS FINAL_SHIPPING_STATUS, CAST(CONCAT(afi.ORDER_ID, \'-\', afi.PRODUCT_ID) AS STRING) AS SALEORDERITEMCODE, CAST(CONCAT(afi.ORDER_ID, \'-\', afi.PRODUCT_ID) AS STRING) AS SALES_ORDER_ITEM_ID, CAST(AWB AS STRING) AS AWB, CAST(Payment_Gateway AS STRING) AS Payment_Gateway, CAST(NULL AS STRING) AS Payment_Mode, CAST(courier_name AS STRING) AS COURIER, CAST(dispatched_date AS date) AS DISPATCH_DATE, CAST(paid_date AS date) AS paid_date, CAST(NULL AS TIMESTAMP) AS DELIVERED_DATE, CASE WHEN LOWER(order_status) LIKE \'delive%\' THEN 1 ELSE 0 END AS DELIVERED_STATUS, CASE WHEN prod_refund_amount IS NOT NULL THEN 1 ELSE 0 END AS RETURN_FLAG, CAST(0 AS FLOAT64) AS returned_quantity, CAST(prod_refund_amount AS FLOAT64) AS returned_sales, CASE WHEN LOWER(afi.order_status) LIKE \'cancel%\' THEN CAST(afi.product_qty AS FLOAT64) END AS cancelled_quantity, CAST(NULL AS STRING) AS NEW_CUSTOMER_FLAG, CAST(NULL AS STRING) AS ACQUISITION_PRODUCT, CASE WHEN LOWER(order_status) IN (\'delivered\', \'delivered to origin\') THEN DATE_DIFF(CAST(CURRENT_DATE() AS DATE), CAST(afi.ORDER_TIMESTAMP AS DATE), DAY) WHEN LOWER(order_status) IN (\'in transit\', \'shipment created\') THEN DATE_DIFF(CAST(CURRENT_DATE() AS DATE), CAST(afi.ORDER_TIMESTAMP AS DATE), DAY) END AS Days_in_Shipment, CAST(afi.SKU AS STRING) AS SKU_CODE, CAST(UPPER(AFI.product_name) AS STRING) AS PRODUCT_NAME_FINAL, CAST(UPPER(AFI.PRODUCT_CATEGORY) AS STRING) AS PRODUCT_CATEGORY, CAST(PRODUCT_SUB_CATEGORY AS STRING) AS PRODUCT_SUB_CATEGORY, CAST(afi.SKU AS STRING) AS commonsku, CAST(NULL AS STRING) AS WAREHOUSE, CAST(zipcode AS STRING) AS pincode, CAST(NULL AS STRING) AS source_pincode, CAST(NULL AS STRING) AS discount_codes, CAST(order_date AS TIMESTAMP) Return_date, Product_Cost, Product_Other_Cost, transaction_id, Order_Date_Flag, Paid_date_Flag, DSF_Cost, shipping_cost_amz, additional_amount, coalesce(ga4.transactionid,ga4_new.transactionid) as ga4_transactionid , order_channel, amazon_ppc_fee, Amazon_order_date FROM maplemonk.website_marketplace_fact_items AS afi left join ( select transactionid, customChannelGroup as final_source, customChannelGroup channel from maplemonk.CC_GA_CUSTOM_ORDER_BY_SOURCE_CONSOLIDATED qualify row_number() over (partition by replace(transactionid, \'#\',\'\') order by 1) =1 ) GA4 on replace(cast(AFI.order_id as string),\'#\',\'\') = replace(GA4.transactionid, \'#\',\'\') left join ( select transactionid, customChannelGroup as final_source, customChannelGroup channel from maplemonk.CC_GA_CUSTOM_ORDER_BY_SOURCE_CONSOLIDATED qualify row_number() over (partition by replace(transactionid, \'#\',\'\') order by 1) =1 ) GA4_new on replace(cast(AFI.shopify_order_id as string),\'#\',\'\') = replace(GA4_new.transactionid, \'#\',\'\') ; CREATE OR REPLACE TABLE maplemonk.Final_customerID AS WITH new_phone_numbers AS ( SELECT phone, contact_num, 19700000000 + ROW_NUMBER() OVER (ORDER BY contact_num ASC) AS maple_monk_id FROM ( SELECT DISTINCT phone AS contact_num, phone FROM maplemonk.CC_sales_consolidated_intermediate ) a ), INT AS ( SELECT contact_num, email, COALESCE(maple_monk_id, id2) AS maple_monk_id FROM ( SELECT contact_num, email, maple_monk_id, 19800000000 + ROW_NUMBER() OVER (PARTITION BY maple_monk_id IS NULL ORDER BY email ASC) AS id2 FROM ( SELECT DISTINCT COALESCE(p.contact_num,e.contact_num) AS contact_num, e.email, maple_monk_id FROM ( SELECT phone AS contact_num, email FROM maplemonk.CC_sales_consolidated_intermediate ) e LEFT JOIN new_phone_numbers p ON p.contact_num = e.contact_num ) a ) b ) SELECT contact_num, email, maple_monk_id FROM INT WHERE COALESCE(contact_num, email) IS NOT NULL; CREATE OR REPLACE TABLE maplemonk.CC_sales_consolidated AS SELECT COALESCE(m.maple_monk_id_phone, d.maple_monk_id) AS customer_id_final, MIN(order_date) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS acquisition_date, MIN(CASE WHEN LOWER(order_status) NOT IN (\'cancelled\') THEN order_date END) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS first_complete_order_date, sum(ifnull(quantity, 0)) over(partition by reference_code order by 1) Order_Quantity, m.* FROM ( SELECT c.maple_monk_id AS maple_monk_id_phone, o.* FROM maplemonk.CC_sales_consolidated_intermediate o LEFT JOIN ( SELECT * FROM ( SELECT contact_num AS phone, maple_monk_id, ROW_NUMBER() OVER (PARTITION BY contact_num ORDER BY maple_monk_id ASC) AS magic FROM maplemonk.Final_customerID ) WHERE magic = 1 ) c ON c.phone = o.phone ) m LEFT JOIN ( SELECT DISTINCT maple_monk_id, email FROM maplemonk.Final_customerID WHERE contact_num IS NULL ) d ON d.email = m.email ; ALTER TABLE maplemonk.CC_sales_consolidated DROP COLUMN IF EXISTS new_customer_flag, DROP COLUMN IF EXISTS acquisition_product; ALTER TABLE maplemonk.CC_sales_consolidated ADD COLUMN new_customer_flag STRING, ADD COLUMN new_customer_flag_month STRING, ADD COLUMN acquisition_product STRING, ADD COLUMN acquisition_channel STRING, ADD COLUMN acquisition_marketplace STRING; UPDATE maplemonk.CC_sales_consolidated AS A SET A.new_customer_flag = B.flag FROM ( SELECT order_id, customer_id_final, Order_Date, CASE WHEN Order_Date = first_complete_order_date THEN \'New\' WHEN Order_Date < first_complete_order_date OR first_complete_order_date IS NULL THEN \'Yet to make completed order\' WHEN Order_Date > first_complete_order_date THEN \'Repeat\' END AS Flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM maplemonk.CC_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw =1; UPDATE maplemonk.CC_sales_consolidated SET new_customer_flag = CASE WHEN new_customer_flag IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' WHEN new_customer_flag IS NULL AND LOWER(order_status) IN (\'cancelled\') THEN \'Yet to make completed order\' ELSE new_customer_flag END WHERE new_customer_flag IS NULL; UPDATE maplemonk.CC_sales_consolidated AS A SET A.new_customer_flag_month = B.flag FROM ( SELECT DISTINCT order_id, customer_id_final, order_date, CASE WHEN DATE_TRUNC(order_date, MONTH) = DATE_TRUNC(first_complete_order_date, MONTH) THEN \'New\' WHEN DATE_TRUNC(order_date, MONTH) < DATE_TRUNC(first_complete_order_date, MONTH) OR acquisition_date IS NULL THEN \'Yet to make completed order\' WHEN DATE_TRUNC(order_date, MONTH) > DATE_TRUNC(first_complete_order_date, MONTH) THEN \'Repeat\' END AS flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM maplemonk.CC_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw=1; UPDATE maplemonk.CC_sales_consolidated SET new_customer_flag_month = CASE WHEN new_customer_flag_month IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' ELSE new_customer_flag_month END WHERE new_customer_flag_month IS NULL; CREATE OR REPLACE TEMPORARY TABLE temp_source_1 AS SELECT customer_id_final, source AS channel, shop_name AS marketplace FROM (SELECT * FROM( SELECT customer_id_final, order_date, source, shop_name, MIN(CASE WHEN LOWER(order_status) <> \'cancelled\' THEN order_date END) OVER (PARTITION BY customer_id_final) AS firstOrderDate, row_number() over (partition by customer_id_final order by ORDER_TIME) rw FROM maplemonk.CC_sales_consolidated ) AS res where rw =1 ) WHERE order_date = firstOrderDate; UPDATE maplemonk.CC_sales_consolidated AS a SET a.acquisition_channel = b.channel FROM temp_source_1 AS b WHERE a.customer_id_final = b.customer_id_final; UPDATE maplemonk.CC_sales_consolidated AS a SET a.acquisition_marketplace = b.marketplace FROM temp_source_1 AS b WHERE a.customer_id_final = b.customer_id_final; CREATE OR replace temporary TABLE temp_product_1 AS SELECT customer_id_final, product_name_final FROM ( SELECT customer_id_final, order_date, product_name_final, SELLING_PRICE , Min(case when lower(order_status) <> \'cancelled\' then order_date end) OVER (partition BY customer_id_final) firstOrderdate, row_number() over (partition by customer_id_final order by ORDER_TIME asc, SELLING_PRICE desc) rw FROM maplemonk.CC_sales_consolidated )res WHERE order_date=firstorderdate and rw=1; UPDATE maplemonk.CC_sales_consolidated AS A SET A.acquisition_product = B.product_name_final FROM ( SELECT * FROM temp_product_1 ) AS B WHERE A.customer_id_final = B.customer_id_final; CREATE OR REPLACE TABLE maplemonk.CC_sales_consolidated AS (Select customer_id_final, acquisition_date, first_complete_order_date, Order_Quantity, maple_monk_id_phone, coalesce(sc.region,cf.region,up.region) Region, delivery_country, customer_id, Business_Segment, coalesce(sc.brand,up.brand) as Brand, Shop_name, coalesce(sc.marketplace,cf.marketplace,up.marketplace) marketplace, sc.CHANNEL as CHANNEL, SOURCE, Affiliates, aff_net_name, order_id, reference_code, phone, name, email, SHIPPING_LAST_UPDATE_DATE, sku, product_id, product_name, CURRENCY, City, State, Order_Status, coalesce(order_date,cf.date) as order_date, Order_Time, quantity, GROSS_SALES_BEFORE_TAX, DISCOUNT, TAX, SHIPPING_PRICE, SELLING_PRICE, OMS_order_status, SHIPPING_STATUS, FINAL_SHIPPING_STATUS, SALEORDERITEMCODE, SALES_ORDER_ITEM_ID, AWB, Payment_Gateway, Payment_Mode, COURIER, DISPATCH_DATE, coalesce(paid_date,cf.date,paid_date1) paid_date, DELIVERED_DATE, DELIVERED_STATUS, RETURN_FLAG, returned_quantity, returned_sales, cancelled_quantity, Days_in_Shipment, SKU_CODE, PRODUCT_NAME_FINAL, PRODUCT_CATEGORY, PRODUCT_SUB_CATEGORY, commonsku, WAREHOUSE, pincode, source_pincode, discount_codes, new_customer_flag, new_customer_flag_month, acquisition_product, acquisition_channel, acquisition_marketplace, Product_Cost, Product_Other_Cost, safe_divide(selling_price , SUM(selling_price) OVER (PARTITION BY sc.order_id)) as Percent, null as Refund_Amount, safe_divide(selling_price , SUM(selling_price) OVER (PARTITION BY sc.order_id)) * ifnull(amazon_comm,0) as amazon_comm, safe_divide(ifnull(chargeback,0) ,count(*) OVER (PARTITION BY coalesce(sc.paid_date,cf.date,paid_date1) , coalesce(lower(sc.marketplace),lower(cf.marketplace),lower(up.marketplace)), coalesce(lower(sc.region),lower(cf.region),lower(up.region) ), coalesce(lower(sc.region),lower(cf.region),lower(up.region) ), coalesce(Paid_date_Flag,Paid_date_Flag1))) as chargeback_amount, safe_divide(selling_price , SUM(selling_price) OVER (PARTITION BY sc.order_id)) * ifnull(storage_fee,0) as storage_fee, safe_divide(selling_price , SUM(selling_price) OVER (PARTITION BY sc.order_id)) * ifnull(Outbound_Charges,0) as Outbound_Charges, safe_divide(selling_price , SUM(selling_price) OVER (PARTITION BY sc.order_id)) * ifnull(removal_charges,0) as removal_charges, null as Affiliation_Cost, null as spend, ifnull(Order_Date_Flag,0) Order_Date_Flag, ifnull(coalesce(Paid_date_Flag,Paid_date_Flag1),0) Paid_date_Flag, 0 as returns_union, 0 as Return_product_cost, 0 as Return_tax, DSF_Cost, shipping_cost_amz, additional_amount, ga4_transactionid, order_channel as backend_channel, amazon_ppc_fee, Amazon_order_date, safe_divide(ifnull(total_quantity,0) ,count(*) OVER (PARTITION BY coalesce(paid_date,cf.date,paid_date1), lower(coalesce(sc.brand,up.brand)), lower(coalesce(sc.region,cf.region,up.region)), lower(coalesce(sc.marketplace,cf.marketplace,up.marketplace)), coalesce(Paid_date_Flag,Paid_date_Flag1) )) as updated_total_quantity, safe_divide(ifnull(total_product_cost,0) ,count(*) OVER (PARTITION BY coalesce(paid_date,cf.date,paid_date1), lower(coalesce(sc.brand,up.brand)), lower(coalesce(sc.region,cf.region,up.region)), lower(coalesce(sc.marketplace,cf.marketplace,up.marketplace)), coalesce(Paid_date_Flag,Paid_date_Flag1) )) as updated_total_product_cost from MAPLEMONK.CC_sales_consolidated SC left join ( select order_id as op_order_id ,sum(ifnull(amazon_comm,0)) amazon_comm ,sum(ifnull(storage_fee,0)) storage_fee ,sum(ifnull(postage_fee,0)) Outbound_Charges ,sum(ifnull(removal_charges,0)) removal_charges from cc_comfort_db.order_processing group by 1 )op on lower(cast(op.op_order_id as string)) = lower(cast(sc.order_id as string)) full outer join ( select paid_date as paid_date1 , \'WEBSITE\' as marketplace, 1 as paid_date_flag1, coalesce(upper(market),\'Others\') region, coalesce(upper(brand),\'Others\') brand, sum(ifnull(total_quantity,0)) as total_quantity, sum(ifnull(total_product_cost,0)) as total_product_cost from CC_DATA_TEAM.units_productcost_table where paid_date is not null group by 1,2,3,4,5 )up on sc.paid_date = up.paid_date1 and lower(sc.marketplace) = lower(up.marketplace) and lower(sc.region) = lower(up.region) and lower(sc.brand) = lower(up.brand) and Paid_date_Flag = paid_date_flag1 full outer join maplemonk.chargeback_fact_itmes cf on coalesce(paid_date,paid_date1) = cf.date and lower(coalesce(sc.marketplace,up.marketplace)) = lower(cf.marketplace) and lower(coalesce(sc.region,up.region)) = lower(cf.region) and coalesce(Paid_date_Flag,paid_date_flag1) = 1 ) union all ( Select null customer_id_final, null acquisition_date, null first_complete_order_date, null Order_Quantity, null maple_monk_id_phone, region, null delivery_country, null customer_id, null Business_Segment, brand, marketplace as Shop_name, marketplace, Channel, null SOURCE, null Affiliates, null aff_net_name, opr_order_id order_id, opr_order_id reference_code, null phone, null name, null email, null SHIPPING_LAST_UPDATE_DATE, sku, null product_id, null product_name, null CURRENCY, null City, null State, null Order_Status, refund_date as Order_date, null Order_Time, null quantity, null GROSS_SALES_BEFORE_TAX, null DISCOUNT, null TAX, null SHIPPING_PRI