null(mc_ppc.Conversion_Value,0) , count(*) OVER (PARTITION BY coalesce(order_date,mc_ppc.date,dsp.date) ,lower(coalesce(sc.CHANNEL,mc_ppc.channel,dsp.Channel)) ,lower(coalesce(sc.region,mc_ppc.region,dsp.region)) ,lower(coalesce(sc.brand,mc_ppc.brand)) )) as Conversion_Value, safe_divide(ifnull(dsp.Dsp_Spend,0) , count(*) OVER (PARTITION BY coalesce(order_date,dsp.date,mc_ppc.date) ,lower(coalesce(sc.region,dsp.region,mc_ppc.region)) ,lower(coalesce(sc.CHANNEL,mc_ppc.channel,dsp.Channel)) )) as Dsp_Spend from (select * from MAPLEMONK.CC_sales_consolidated where Order_Date_Flag = 1)SC left join ( select cast(paid_date as string) as order_date1 ,region ,brand ,marketplace as channel1 ,sum(case when ifnull(shipping_site_id,12333) != 29 then ifnull(shipping_cost_amz,0) else 0 end) Postage_Customer from maplemonk.website_marketplace_fact_items group by 1,2,3,4 )sc1 on cast(sc1.order_date1 as date) = cast(sc.order_date as date) and lower(sc1.channel1) = lower(sc.marketplace) and lower(sc1.region) = lower(sc.region) and lower(sc1.brand) = lower(sc.brand) full outer join ( select case when lower(channel) like any (\'%google%\',\'%bing%\') then \'PPC\' when lower(channel) like any (\'%SEO%\') then \'SEO\' when lower(channel) like any (\'%facebook%\') then \'SOCIAL MEDIA\' when lower(channel) like any (\'%affiliate%\') then \'AFFILIATES\' else channel end as Channel ,date ,region ,brand ,sum(ifnull(spend,0)) Spend ,sum(ifnull(Conversion_Value,0)) as Conversion_Value from `MAPLEMONK.CC_MARKETING_CONSOLIDATED` group by 1,2,3,4 )mc_ppc on cast(mc_ppc.date as date) = cast(sc.order_date as date) and lower(mc_ppc.channel) = lower(sc.channel) and lower(mc_ppc.region) = lower(sc.region) and lower(mc_ppc.brand) = lower(sc.brand) full outer join ( select PARSE_DATE(\'%Y-%m-%d\', date) date, trim(upper(Market)) as region, \'AMAZON\' as Channel, ifnull(cast(mc.Total_Cost as float64),0)/ifnull(rh.er_exchange_rate,1) as Dsp_Spend, from `MAPLEMONK.DSP_Daily_Spends_Sheet1` mc left join ( select * from `cc_comfort_db.exchange_rate_history` qualify row_number() over(partition by cast(er_date as date),upper(er_currency_name) ) =1 )rh on cast(rh.er_date as date) = PARSE_DATE(\'%Y-%m-%d\', mc.date) and upper(trim(mc.currency)) = upper(trim(rh.er_currency_name)) ) dsp on cast(coalesce(mc_ppc.date,sc.order_date) as date) = dsp.date and lower(cast(coalesce(mc_ppc.region,sc.region) as string)) = lower(dsp.region) and lower(cast(coalesce(mc_ppc.Channel,sc.Channel) as string)) = lower(dsp.Channel) ; CREATE OR REPLACE TABLE maplemonk.CC_PANDL_PAID AS SELECT customer_id_final, acquisition_date, first_complete_order_date, Order_Quantity, maple_monk_id_phone, COALESCE(sc.region, mc_ppc.region, dsp.region) AS region, delivery_country, customer_id, Business_Segment, COALESCE(sc.brand, mc_ppc.brand) AS brand, Shop_name, UPPER(COALESCE(marketplace, CASE WHEN LOWER(COALESCE(sc.CHANNEL, mc_ppc.channel, dsp.channel)) LIKE \'%amazon%\' THEN \'AMAZON\' WHEN LOWER(COALESCE(sc.CHANNEL, mc_ppc.channel, dsp.channel)) IS NOT NULL THEN \'WEBSITE\' END )) AS marketplace, COALESCE(sc.CHANNEL, mc_ppc.channel) AS Channel, SOURCE, order_id, reference_code, phone, name, email, SHIPPING_LAST_UPDATE_DATE, sku, product_id, product_name, CURRENCY, City, State, Order_Status, COALESCE(paid_date, mc_ppc.date, dsp.date) AS paid_date, Order_Time, quantity, GROSS_SALES_BEFORE_TAX, DISCOUNT, TAX, CASE WHEN NOT(LOWER(IFNULL(marketplace, \'\')) LIKE \'%website%\') THEN IFNULL(shipping_cost_amz, 0) ELSE SHIPPING_PRICE END AS SHIPPING_PRICE, shipping_cost_amz AS shipping_charge, SELLING_PRICE, OMS_order_status, SHIPPING_STATUS, FINAL_SHIPPING_STATUS, SALEORDERITEMCODE, SALES_ORDER_ITEM_ID, AWB, Payment_Gateway, Payment_Mode, COURIER, DISPATCH_DATE, DELIVERED_DATE, DELIVERED_STATUS, RETURN_FLAG, returned_quantity, returned_sales, cancelled_quantity, Days_in_Shipment, SKU_CODE, PRODUCT_NAME_FINAL, PRODUCT_CATEGORY, PRODUCT_SUB_CATEGORY, commonsku, WAREHOUSE, pincode, source_pincode, discount_codes, new_customer_flag, new_customer_flag_month, acquisition_product, acquisition_channel, acquisition_marketplace, Product_Cost, Product_Other_Cost, SAFE_DIVIDE(selling_price, SUM(selling_price) OVER (PARTITION BY sc.order_id)) AS Percent, Refund_Amount, amazon_comm, chargeback_amount, storage_fee, Outbound_Charges, removal_charges, NULL AS Affiliation_Cost, Return_product_cost, Return_tax, DSF_Cost, sc.Postage_Customer, SAFE_DIVIDE(IFNULL(mc_ppc.Spend, 0), COUNT(*) OVER ( PARTITION BY COALESCE(paid_date, mc_ppc.date, dsp.date), LOWER(COALESCE(sc.CHANNEL, mc_ppc.channel, dsp.Channel)), LOWER(COALESCE(sc.region, mc_ppc.region, dsp.region)), LOWER(COALESCE(sc.brand, mc_ppc.brand)) )) AS Spend, SAFE_DIVIDE(IFNULL(dsp.Dsp_Spend, 0), COUNT(*) OVER ( PARTITION BY COALESCE(paid_date, dsp.date, mc_ppc.date), LOWER(COALESCE(sc.region, dsp.region, mc_ppc.region)), LOWER(COALESCE(sc.CHANNEL, mc_ppc.channel, dsp.Channel)) )) AS Dsp_Spend, fulfilment_cost, packaging_cost, amazon_ppc_fee_op, returns_union, cost_per_qty, additional_amount, backend_channel, updated_total_product_cost, updated_total_quantity FROM ( SELECT sc.*, SAFE_DIVIDE(IFNULL(sc1.Postage_Customer, 0), COUNT(*) OVER ( PARTITION BY order_date, LOWER(sc.marketplace), LOWER(sc.region), LOWER(sc.brand) )) AS Postage_Customer, SAFE_DIVIDE(IFNULL(sc2.fulfilment_cost, 0), COUNT(*) OVER (PARTITION BY sc2.order_id)) AS fulfilment_cost, SAFE_DIVIDE(IFNULL(sc2.packaging_cost, 0), COUNT(*) OVER (PARTITION BY sc2.order_id)) AS packaging_cost, SAFE_DIVIDE(IFNULL(sc2.amazon_ppc_fee_op, 0), COUNT(*) OVER (PARTITION BY sc2.order_id)) AS amazon_ppc_fee_op, SAFE_DIVIDE(IFNULL(sc2.cost_per_qty, 0), COUNT(*) OVER (PARTITION BY sc2.order_id)) AS cost_per_qty FROM MAPLEMONK.CC_sales_consolidated sc LEFT JOIN ( SELECT CAST(paid_date AS STRING) AS order_date1, region, brand, marketplace AS channel1, SUM(CASE WHEN IFNULL(shipping_site_id, 12333) != 29 THEN IFNULL(shipping_cost_amz, 0) ELSE 0 END) AS Postage_Customer FROM maplemonk.website_marketpl