 EXTRACT(DAY FROM current_date -1 ) else EXTRACT(DAY FROM (last_day(coalesce(s.date,T.Start_Date)))) end as multily ,EXTRACT(DAY FROM (last_day(coalesce(s.date,T.Start_Date)))) as last_date ,FORMAT_DATE(\'%Y-%B\', DATE (last_day(coalesce(s.date,T.Start_Date)))) as month ,FORMAT_DATE(\'%Y-%m\', DATE (last_day(coalesce(s.date,T.Start_Date)))) as month1 from Sales S full outer join Targets T on s.date = T.Start_Date and lower(s.region) = lower(t.region) and lower(s.brand) = lower(t.brand) ; CREATE OR REPLACE TABLE powerbi-425707.CC_DATA_TEAM.Without_Wimbledon_Base_Query_WPR PARTITION BY paid_date AS with orders_cte as( select om.order_id as orders,dg.abbr as market, case when om.domain_id = 220 and dom_site_brand_name = \'\' then \'WeightWorld\' else dom_site_brand_name end as brand, rh.er_exchange_rate, om.parent_order_id as parent_order_id, om.master_order_id as master_order_id, IFNULL(om.exchange_rate,1) AS exchange_rate, safe_divide((ifnull(cod_price,0)), count(*) over(partition by om.order_id)) as cod_price_pre, case when od.order_id is not null THEN safe_divide((ifnull(om.shipping_charge,0)), count(*) over(partition by om.order_id)) else 0 end as shipping_price_pre, (case when od.order_id is not null then (ifnull(od.total_price,0)) else cast(ifnull(om.order_total,0) as float64) end) as Selling_Price_pre, safe_divide(ifnull(om.additional_added_amount,0), count(*) over(partition by om.order_id)) as additional_amount_pre, SAFE_DIVIDE(IFNULL(CASE WHEN LOWER(om.discount_type) LIKE \'%fixed%\' OR TRIM(om.discount_type) = \'\' THEN om.discount ELSE (om.discount / 100) * om.sub_total END, 0 ), COUNT(*) OVER (PARTITION BY om.order_id)) AS discount, od.prod_vat, od.ship_vat, Other_Cost, od.product_qty as units, safe_divide(op.fulfilment_cost,COUNT(*) OVER (PARTITION BY op.order_id)) as fulfilment_cost, safe_divide(op.packaging_cost,COUNT(*) OVER (PARTITION BY op.order_id)) as packaging_cost, od.per_unit_cost, safe_divide((ifnull(om.cod_cost_price,0)), count(*) over(partition by om.order_id)) as cod_cost_price, safe_divide((ifnull(om.shipping_cost,0)), count(*) over(partition by om.order_id)) as shipping_cost, product_code as sku_code, order_total, op.lost_chargeback_date as lost_chargeback_date, op.decline_reason as decline_reason, op.won_chargeback_date as won_chargeback_date, om.current_status as current_status, od.cost_price as cost_price, od.is_pack as is_pack, od.id as id, od.status as status, op.order_id as op_order_id, op.paid_date as op_paid_date, od.reusable as reusable, od.status as od_status, om.other_status as om_other_status, date(op.resend_date) as resend_date, CASE WHEN LOWER(IFNULL(op.decline_reason, \'\')) NOT LIKE \'%test order%\' AND TRIM(IFNULL(om.payment_gateway, \'\')) != \'\' AND NOT IFNULL(om.current_status, 1) IN (0, 25) AND op.order_id IS NOT NULL THEN 1 ELSE 0 END AS Paid_date_Flag,DATE(op.paid_date) AS paid_date, case when UPPER(pg.pg_status) = \'Y\' AND pg.mpg_id = 11 then \'AMAZON\' else \'WEBSITE\' end as segment from( SELECT order_id, payment_gateway, order_total, domain_id, order_date, currency, exchange_rate, parent_order_id, master_order_id, cod_price, shipping_charge, additional_added_amount, discount_type, discount, sub_total, cod_cost_price, shipping_cost, current_status, other_status FROM cc_comfort_db.order_master QUALIFY ROW_NUMBER() OVER (PARTITION BY order_id ORDER BY 1) = 1 )om LEFT JOIN( SELECT id, order_id, product_code, product_qty, reusable, is_pack, total_price, prod_vat, ship_vat, cost_price, status, ifnull(cast(JSON_EXTRACT_SCALAR(SAFE.PARSE_JSON(json_external_cost), \'$.per_unit_total_qty_cost\') as float64),0) as per_unit_cost FROM cc_comfort_db.order_details WHERE IFNULL(status, 0) = 1 ) od ON od.order_id = om.order_id LEFT JOIN ( SELECT paid_date, resend_date, order_id, lost_chargeback_date, won_chargeback_date, decline_reason, ifnull(cast(JSON_EXTRACT_SCALAR(SAFE.PARSE_JSON(json_external_cost), \'$.fulfilment_cost\') as float64),0) as fulfilment_cost, ifnull(cast(JSON_EXTRACT_SCALAR(SAFE.PARSE_JSON(json_external_cost), \'$.packaging_cost\') as float64),0) as packaging_cost, FROM cc_comfort_db.order_processing WHERE order_id IS NOT NULL QUALIFY ROW_NUMBER() OVER (PARTITION BY order_id ORDER BY 1) = 1 ) op ON op.order_id = om.order_id LEFT JOIN ( SELECT * FROM cc_comfort_db.payment_gateways QUALIFY ROW_NUMBER() OVER (PARTITION BY LOWER(TRIM(IFNULL(gateway_name, \'\'))) ORDER BY 1) = 1 ) pg ON REPLACE(LOWER(TRIM(pg.gateway_name)), \' \', \'\') = REPLACE(LOWER(TRIM(IFNULL(om.payment_gateway, \'\'))), \' \', \'\') left join ( select * from `cc_comfort_db.domains` )d on d.id = om.domain_id left join ( select * from `cc_comfort_db.domains_group` )dg on d.group_id = dg.id left join ( select * from `cc_comfort_db.exchange_rate_history` ) rh on cast(rh.er_date as date) = cast(om.order_date as date) and upper(om.currency) = upper(rh.er_currency_name) left join ( select product_master_id pod_product_master_id ,cast(date as date) as stock_Date ,Sum(ifnull(other_cost ,0)) as Other_Cost from ( (select stockid,cast(stock_date as date)date,Sum(ifnull(other_cost ,0))other_cost from cc_comfort_db.stock_report where cast(stock_date as date) < \'2024-07-01\' or (cast(stock_date as date) >= \'2024-07-01\' and not(concat(stock_date,stockid) in (select distinct concat(stock_date,stockid) from cc_comfort_db.temp_stock_report )) ) group by 1,2 ) union all ( select stockid,cast(stock_date as date)date,Sum(ifnull(other_cost ,0))other_cost from cc_comfort_db.temp_stock_report where cast(stock_date as date) >= \'2024-07-01\' group by 1,2 ) )sr left join ( select stockid, productid product_master_id from cc_comfort_db.stock qualify row_number() over(partition by stockid order by 1) = 1 )s on sr.stockid = s.stockid group by 1,2 ) pod on cast(pod.pod_product_master_id as string) = cast(od.product_code as string) and cast(pod.stock_Date as date) = cast(om.order_date as date) ), sales_quantity_cte AS ( SELECT om.order_id as orders, sum( CASE WHEN TRIM(LOWER(od.is_pack)) = \'yes\' THEN opck.quantity * od.product_qty ELSE od.product_qty END) AS sales_quantity FROM ( SELECT order_id FROM cc_comfort_db.order_master QUALIFY ROW_NUMBER() OVER (PARTITION BY order_id ORDER BY 1) = 1 ) om LEFT JOIN ( (SELECT id,status, order_id, is_pack, product_qty FROM cc_comfort_db.order_details WHERE IFNULL(status, 0) = 1 QUALIFY ROW_NUMBER() OVER (PARTITION BY id) = 1) od LEFT JOIN ( SELECT order_detail_id, SUM(quantity) AS quantity FROM cc_comfort_db.order_package GROUP BY order_detail_id ) opck ON od.id = opck.order_detail_id ) ON od.order_id = om.order_id group by 1 ), Orders_Units_CTE as ( select o.paid_date as paid_date, market, brand, count(distinct o.orders) as Orders, sum(f.sales_quantity) as Sales_Quantity, from sales_quantity_cte f left join (SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY orders) AS rn FROM orders_cte ) WHERE rn = 1) o on o.orders =f.orders where lower(o.segment) = \'website\' and IFNULL(parent_order_id, 1) = 0 and IFNULL(master_order_id, 1) = 0 AND SAFE_CAST(IFNULL(order_total, 1) AS INT64) > 0 and o.paid_date_flag = 1 group by 1, 2, 3 ), Gross_Sales_CTE AS ( select paid_date, market, brand, sum(safe_divide(selling_price_pre,ifnull(exchange_rate,1))+safe_divide(cod_price_pre,ifnull(exchange_rate,1))+safe_divide(shipping_price_pre,ifnull(exchange_rate,1))) as Gross_Sales from orders_cte where lower(segment) = \'website\' and IFNULL(parent_order_id, 1) = 0 and IFNULL(master_order_id, 1) = 0 AND SAFE_CAST(IFNULL(order_total, 1) AS INT64) > 0 and paid_date_flag = 1 group by 1, 2, 3 ), Additional_Amount_CTE AS ( select paid_date, MARKET, brand, sum(case when ifnull(exchange_rate,0) > 0 then ifnull(additional_amount_pre,0)/ifnull(exchange_rate,1) else ifnull(additional_amount_pre,0)/ifnull(er_exchange_rate,1) end )as additional_amount FROM orders_cte where lower(segment) = \'website\' and IFNULL(parent_order_id, 1) = 0 and IFNULL(master_order_id, 1) = 0 AND SAFE_CAST(IFNULL(order_total, 1) AS INT64) > 0 and paid_date_flag = 1 group by 1,2,3 ), Discount_CTE AS ( select paid_date, market, brand, sum(case when ifnull(exchange_rate,0) > 0 then ifnull(discount,0)/ifnull(exchange_rate,1) else ifnull(discount,0)/ifnull(er_exchange_rate,1) end )as discount, FROM orders_cte where lower(segment) = \'website\' and IFNULL(parent_order_id, 1) = 0 and IFNULL(master_order_id, 1) = 0 AND SAFE_CAST(IFNULL(order_total, 1) AS INT64) > 0 and paid_date_flag = 1 group by 1,2,3 ), VAT_CTE AS ( select paid_date, market, brand, SUM(prod_vat) + SUM(ship_vat) AS VAT, FROM orders_cte where lower(segment) = \'website\' and IFNULL(parent_order_id, 1) = 0 and IFNULL(master_order_id, 1) = 0 AND SAFE_CAST(IFNULL(order_total, 1) AS INT64) > 0 and paid_date_flag = 1 group by 1,2, 3 ), Product_Other_Cost_CTE AS ( select paid_date, market, brand, sum(ifnull(Other_Cost,0) * ifnull(units,0)) as Product_Other_Cost, FROM orders_cte where lower(segment) = \'website\' and IFNULL(parent_order_id, 1) = 0 and IFNULL(master_order_id, 1) = 0 AND SAFE_CAST(IFNULL(order_total, 1) AS INT64) > 0 and paid_date_flag = 1 group by 1,2, 3 ), Fulfillment_Packaging_Cost_CTE AS ( select paid_date, market, brand, SUM(fulfilment_cost) AS fulfilment_cost, SUM(packaging_cost) AS packaging_cost, FROM orders_cte where lower(segment) = \'website\' and IFNULL(parent_order_id, 1) = 0 and IFNULL(master_order_id, 1) = 0 AND SAFE_CAST(IFNULL(order_total, 1) AS INT64) > 0 and paid_date_flag = 1 group by 1,2,3 ), WH_Per_Unit_Cost AS ( SELECT paid_date, market, brand, sum(per_unit_cost) as per_unit_cost, FROM orders_cte where lower(segment) = \'website\' and IFNULL(parent_order_id, 1) = 0 and IFNULL(master_order_id, 1) = 0 AND SAFE_CAST(IFNULL(order_total, 1) AS INT64) > 0 and paid_date_flag = 1 group by 1,2,3 ), Shipping_Cost_CTE as ( SELECT paid_date, market, brand, sum(shipping_cost+cod_cost_price) as shipping_cost FROM orders_cte where lower(segment) = \'website\' and IFNULL(parent_order_id, 1) = 0 and IFNULL(master_order_id, 1) = 0 AND SAFE_CAST(IFNULL(order_total, 1) AS INT64) > 0 and paid_date_flag = 1 group by 1,2,3 ), refund_pre_cte as ( Select af.opr_order_id as order_id, refund_date, safe_divide((ifnull(Refund_Amount,0)),count(1) over(partition by ifnull(af.opr_order_id,\'\'),refund_date)) Refund_Amount, sku_code, units, segment, paid_date_flag, market, brand, master_order_id, order_total FROM (select cast(opr_archive_refund_date as date) as refund_date ,cast(opr_order_id as string) opr_order_id ,sum(ifnull(opr_refund_amount,0)) Refund_Amount from (select opr.*,decline_reason from cc_comfort_db.order_partial_refund opr left join (select * from cc_comfort_db.order_processing qualify ROW_NUMBER() over(partition by (ifnull(order_id,0)) order by 1) = 1 )op on cast(opr.opr_order_id as string) = cast(op.order_id as string) ) where upper(opr_refund_status) = \'Y\' and lower(decline_reason) != \'%test order%\' and opr_archive_refund_date is not null and cast(opr_order_id as string) not in (select distinct cast(opr_order_id as string) opr_order_id from mp_public.mp_order_partial_refunds) group by 1,2) as af LEFT JOIN ( SELECT distinct orders as order_id, sku_code, paid_date, paid_date_flag, units, segment, market, brand, parent_order_id, master_order_id, order_total from orders_cte WHERE orders is not null ) oc on replace(ifnull(cast(af.opr_order_id as string),\'\'),\' \',\'\') = replace(ifnull(cast(oc.order_id as string),\'\'),\' \',\'\') UNION ALL Select cast(opr_order_id as string) as order_id, refund_date, final_refund_amount as Refund_Amount, sku_code, units, segment, paid_date_flag, market, brand, master_order_id, order_total FROM ( select cast(opr_archive_refund_date as date) as refund_date, opr_order_id ,opr_stock_code ,sum(safe_divide(ifnull(cast(JSON_EXTRACT_SCALAR((refund_details), \'$.final_refund_amount\') as float64),0) , ifnull(opr_refund_exchange_rate,1))) final_refund_amount ,sum(safe_divide(ifnull(cast(JSON_EXTRACT_SCALAR((refund_details), \'$.final_vat_amount\') as float64),0),ifnull(opr_refund_exchange_rate,1))) final_vat_amount from mp_public.mp_order_partial_refunds group by 1,2,3 )opr LEFT JOIN ( SELECT distinct orders as order_id, sku_code, paid_date, paid_date_flag, units, segment, market, brand, parent_order_id, master_order_id, order_total from orders_cte qualify row_number() over(partition by ifnull(cast(order_id as string),\'\'),ifnull(sku_code,\'\')) = 1 ) oc on cast(opr.opr_order_id as string)= cast(oc.order_id as string) and cast(opr.opr_stock_code as string)= cast(oc.SKU_CODE as string) ), Refunds_CTE AS ( select refund_date as paid_date, market, brand, sum(refund_amount) as refund from refund_pre_cte WHERE lower(segment) = \'website\' and IFNULL(master_order_id, 1) = 0 AND SAFE_CAST(IFNULL(order_total, 1) AS INT64) > 0 AND paid_date_flag = 1 group by 1,2,3 ), lost_chargeback_cte AS ( SELECT CAST(lost_chargeback_date AS date) chargeback_date, segment, market, brand, SUM(IFNULL(chargeback,0)) lost_chargeback FROM ( SELECT orders,segment, market, brand, lost_chargeback_date, decline_reason, SAFE_DIVIDE(order_total,IFNULL(exchange_rate,1)) AS chargeback FROM orders_cte QUALIFY ROW_NUMBER() OVER(PARTITION BY orders ORDER BY 1) = 1 ) WHERE lost_chargeback_date IS NOT NULL AND LOWER(segment)=\'website\' AND NOT(LOWER(IFNULL(decline_reason,\'\')) LIKE \'%test order%\') GROUP BY 1,2,3,4 ), won_chargeback_cte AS ( SELECT CAST(won_chargeback_date AS date) chargeback_date, segment, market, brand, SUM(IFNULL(chargeback,0)) won_chargeback FROM ( SELECT orders,segment, market, brand, won_chargeback_date, decline_reason, current_status, SAFE_DIVIDE(order_total,IFNULL(exchange_rate,1)) AS chargeback FROM orders_cte QUALIFY ROW_NUMBER() OVER(PARTITION BY orders ORDER BY 1) = 1 ) WHERE won_chargeback_date IS NOT NULL AND LOWER(segment)=\'website\' AND NOT(LOWER(IFNULL(decline_reason,\'\')) LIKE \'%test order%\') AND ifnull(current_status, 0) = 14 GROUP BY 1,2,3,4 ), Chargeback_CTE AS ( SELECT COALESCE(lc.chargeback_date, wc.chargeback_date) AS paid_date, COALESCE(lc.market, wc.market) AS market, COALESCE(lc.brand, wc.brand) AS brand, SUM(IFNULL(lc.lost_chargeback, 0)) - SUM(IFNULL(wc.won_chargeback, 0)) AS net_chargeback FROM lost_chargeback_cte lc FULL OUTER JOIN won_chargeback_cte wc ON lc.chargeback_date = wc.chargeback_date AND LOWER(lc.segment) = LOWER(wc.segment) AND LOWER(lc.market) = LOWER(wc.market) AND LOWER(lc.brand) = LOWER(wc.brand) GROUP BY 1,2,3 ), Product_Cost_CTE AS ( select paid_date, market, brand, sum(units*cost_price) as sales_product_cost, FROM orders_cte where lower(segment) = \'website\' and IFNULL(parent_order_id, 1) = 0 and IFNULL(master_order_id, 1) = 0 AND SAFE_CAST(IFNULL(order_total, 1) AS INT64) > 0 and paid_date_flag = 1 group by 1,2, 3 ), Refund_Units_CTE as ( select date(opr_archive_refund_date) as paid_date, market, brand, sum(units) as refund_reuse_quantity, sum(units*cost_price) as refund_reuse_product_cost from orders_cte left join ( select * from cc_comfort_db.order_partial_refund ) opr on op_order_id = opr.opr_order_id where lower(segment) = \'website\' and IFNULL(parent_order_id, 1) = 0 and IFNULL(master_order_id, 1) = 0 AND SAFE_CAST(IFNULL(order_total, 1) AS INT64) > 0 and opr_refund_status = \'Y\' AND reusable in (\'Returned Reusable\', \'Returned Reusable\') and paid_date_flag = 1 group by 1,2,3 ), Return_Reusable_Unist_CTE AS ( select paid_date, market, brand, sum(units) as return_reusable_quantity, sum(units*cost_price) as return_reusable_product_cost from orders_cte where lower(segment) = \'website\' and IFNULL(parent_order_id, 1) = 0 and IFNULL(master_order_id, 1) = 0 AND SAFE_CAST(IFNULL(order_total, 1) AS INT64) > 0 AND reusable in (\'Returned Reusable\', \'Returned Reusable\') and paid_date_flag = 1 group by 1,2,3 ), Resend_Master_orders_CTE AS ( SELECT distinct orders, resend_date from orders_cte where lower(segment) = \'website\' AND current_status NOT IN (0,4,25) AND om_other_status = 17 AND od_status <> 0 and paid_date_flag = 1 ) , Resend_Units_CTE AS ( SELECT rmo.resend_date as paid_date, market, brand, sum(units) as resend_quantity, sum(units*cost_price) as resend_units_product_cost from orders_cte LEFT JOIN ( SELECT * FROM Resend_Master_orders_CTE )rmo ON master_order_id = rmo.orders where reusable != \'Returned Reusable\' AND od_status <> 0 and paid_date_flag=1 and paid_date is not null AND master_order_id IN (select orders from Resend_Master_orders_CTE) group by 1,2,3 ) , Units_ProductCost_CTE AS ( SELECT COALESCE(s.paid_date, r.paid_date) AS paid_date, COALESCE(s.market, r.market) AS market, COALESCE(s.brand, r.brand) AS brand, sum(IFNULL(s.sales_quantity, 0) + IFNULL(r.resend_quantity, 0)-ifnull(rf.refund_reuse_quantity, 0)-ifnull(rr.return_reusable_quantity, 0)) AS total_quantity, sum(IFNULL(p.sales_product_cost, 0) + IFNULL(r.resend_units_product_cost, 0)-ifnull(rf.refund_reuse_product_cost, 0)-ifnull(rr.return_reusable_product_cost, 0)) AS total_product_cost FROM Orders_Units_CTE s full outer JOIN Resend_Units_CTE r ON s.paid_date = r.paid_date AND s.market = r.market AND s.brand = r.brand LEFT JOIN Refund_Units_CTE rf on s.paid_date = rf.paid_date and s.market = rf.market AND s.brand = rf.brand LEFT JOIN Return_Reusable_Unist_CTE rr on s.paid_date = rr.paid_date and s.market = rr.market AND s.brand = rr.brand LEFT JOIN Product_Cost_CTE p on s.paid_date = p.paid_date and s.market = p.market AND s.brand = p.brand group by 1, 2, 3 ) , net_sale_cte AS ( SELECT g.paid_date, g.market, g.brand, SUM(IFNULL(g.gross_sales,0)) + SUM(IFNULL(a.additional_amount,0)) - SUM(IFNULL(d.discount,0)) - SUM(IFNULL(r.refund,0)) - SUM(IFNULL(cb.net_chargeback,0)) AS net_sale FROM Orders_Units_CTE o LEFT JOIN Gross_Sales_CTE g ON o.paid_date = g.paid_date AND o.market = g.market and o.brand = g.brand left JOIN Additional_Amount_CTE a ON o.paid_date = a.paid_date AND o.market = a.market and o.brand = a.brand left JOIN Discount_CTE d ON o.paid_date = d.paid_date AND o.market = d.market and o.brand = d.brand left JOIN Chargeback_CTE cb ON o.paid_date = cb.paid_date AND o.market = cb.market and o.brand = cb.brand left JOIN Refunds_CTE r ON o.paid_date = r.paid_date AND o.market = r.market and o.brand = r.brand GROUP BY 1,2,3 ), BB_Influencer_Cost_Pre AS ( SELECT DATE AS paid_date, SUM(CASE WHEN region IS NULL THEN marketing_spend ELSE 0 END) AS BB_Influencer_Cost FROM `powerbi-425707.CC_DATA_TEAM.CC_No_Wimbledon_Sales_Cost_Source_PD` WHERE LOWER(marketplace) = \'website\' AND marketing_spend IS NOT NULL GROUP BY 1 ), BB_Influencer_Cost_CTE as ( SELECT COALESCE(N.paid_date, B.PAID_DATE) as paid_date, n.market, n.brand, n.net_sale, b.BB_Influencer_Cost, CASE WHEN LOWER(n.brand) = \'weightworld\' AND LOWER(n.market) != \'ie\' THEN IFNULL(b.BB_Influencer_Cost, 0) / NULLIF( COUNT(DISTINCT CASE WHEN LOWER(n.brand) = \'weightworld\' AND LOWER(n.market) != \'ie\' THEN n.market END) OVER (PARTITION BY n.paid_date), 0) ELSE 0 END AS Allocated_BB_Influencer_Cost, FROM net_sale_cte n LEFT JOIN BB_Influencer_Cost_Pre b on n.paid_date = b.paid_date ), Total_Marketing_Spend_CTE AS ( select date as paid_date, region as market, brand, sum(case when lower(custom_marketing_channel) in (\'social media\', \'snapchat\', \'tiktok\') then marketing_spend else 0 end) as Social_Media_Cost, sum(case when lower(custom_marketing_channel) like \'%aff%\' then marketing_spend else 0 end) as Affiliate_Cost, sum(case when lower(custom_marketing_channel) like \'%ppc%\' then marketing_spend else 0 end) as PPC_Cost, sum(case when lower(custom_marketing_channel) like \'%seo%\' then marketing_spend else 0 end) as SEO_Cost, sum(ifnull(marketing_spend,0)) as Marketing_Spend from `powerbi-425707.CC_DATA_TEAM.CC_No_Wimbledon_Sales_Cost_Source_PD` where lower(marketplace) = \'website\' and marketing_spend is not null and region is not null group by 1,2,3 ) SELECT COALESCE(MS.paid_date, O.PAID_DATE) as paid_date, COALESCE(CASE WHEN LOWER(MS.market) = \'de\' OR LOWER(MS.market) = \'de + at\' or LOWER(MS.market) = \'fi\' THEN \'DE\' ELSE MS.market END , CASE WHEN LOWER(O.market) = \'de\' OR LOWER(O.market) = \'de + at\' or LOWER(O.market) = \'fi\' THEN \'DE\' ELSE O.market END ) as updated_region, COALESCE( UPPER( CASE WHEN UPPER(MS.market) = \'DE\' OR UPPER(MS.market) = \'DE + AT\' AND (LOWER(MS.brand) = \'weightworld\' OR TRIM(LOWER(MS.brand)) = \'slimcenter\') THEN \'WeightWorld\' ELSE MS.brand END ), UPPER( CASE WHEN UPPER(MS.market) = \'DE\' OR UPPER(MS.market) = \'DE + AT\' AND (LOWER(O.brand) = \'weightworld\' OR TRIM(LOWER(O.brand)) = \'slimcenter\') THEN \'WeightWorld\' ELSE O.brand END ) ) AS updated_brand, SUM(IFNULL(o.Orders, 0)) AS Orders, SUM(IFNULL(pc.total_quantity, 0)) AS quantity, SUM(IFNULL(g.Gross_Sales, 0)) AS GROSS_SALES_BEFORE_TAX, SUM(IFNULL(a.Additional_Amount, 0)) AS additional_amount, SUM(IFNULL(d.Discount, 0)) AS DISCOUNT, SUM(IFNULL(r.Refund, 0)) AS Refund_Amount, SUM(IFNULL(cb.net_chargeback, 0)) AS chargeback_amount, SUM(IFNULL(v.VAT, 0)) AS TAX, SUM(IFNULL(pc.total_product_cost, 0)) AS Product_Cost, SUM(IFNULL(poc.product_other_cost, 0)) AS Product_Other_Cost, SUM(IFNULL(fp.fulfilment_cost, 0)) AS fulfilment_cost, SUM(IFNULL(puc.per_unit_cost, 0)) AS cost_per_qty, SUM(IFNULL(fp.packaging_cost, 0)) AS packaging_cost, SUM(IFNULL(sc.shipping_cost, 0)) AS shipping_charge, SUM(IFNULL(ms.Social_Media_Cost, 0)) AS Social_Media_Cost, SUM(IFNULL(ms.Affiliate_Cost, 0)) AS Affiliate_Cost, SUM(IFNULL(ms.PPC_Cost, 0)) AS PPC_Cost, SUM(IFNULL(ms.SEO_Cost, 0)) AS SEO_Cost, sum(IFNULL(bb.Allocated_BB_Influencer_Cost,0)) as BB_Influencer_Cost, sum(IFNULL(ms.Social_Media_Cost,0))+sum(IFNULL(ms.Affiliate_Cost,0))+sum(IFNULL(ms.PPC_Cost,0))+sum(IFNULL(ms.SEO_Cost,0))+sum(IFNULL(bb.Allocated_BB_Influencer_Cost,0)) as spend from Orders_Units_CTE o left JOIN Gross_Sales_CTE g ON o.paid_date = g.paid_date AND o.market = g.market and o.brand = g.brand left JOIN Additional_Amount_CTE a ON o.paid_date = a.paid_date AND o.market = a.market and o.brand = a.brand left JOIN Discount_CTE d ON o.paid_date = d.paid_date AND o.market = d.market and o.brand = d.brand left JOIN VAT_CTE v on o.paid_date = v.paid_date AND o.market = v.market and o.brand = v.brand left JOIN Refunds_CTE r ON o.paid_date = r.paid_date AND o.market = r.market and o.brand = r.brand left JOIN Product_Other_Cost_CTE poc ON o.paid_date = poc.paid_date AND o.market = poc.market and o.brand = poc.brand left JOIN Fulfillment_Packaging_Cost_CTE fp ON o.paid_date = fp.paid_date AND o.market = fp.market and o.brand = fp.brand left JOIN WH_Per_Unit_Cost PUC ON o.paid_date = PUC.paid_date AND o.market = PUC.market and o.brand = puc.brand left JOIN Shipping_Cost_CTE sc ON o.paid_date = sc.paid_date AND o.market = sc.market and o.brand = sc.brand left JOIN Chargeback_CTE cb ON o.paid_date = cb.paid_date AND o.market = cb.market and o.brand = cb.brand FULL OUTER JOIN Total_Marketing_Spend_CTE ms ON safe_cast(o.paid_date as date) = safe_cast(ms.paid_date as date) AND trim(lower(o.market)) = trim(lower(ms.market)) and trim(lower(o.brand)) = trim(lower(ms.brand)) FULL OUTER JOIN BB_Influencer_Cost_CTE bb ON safe_cast(o.paid_date as date) = safe_cast(bb.paid_date as date) AND trim(lower(o.market)) = trim(lower(bb.market)) and trim(lower(o.brand)) = trim(lower(bb.brand)) left JOIN Units_ProductCost_CTE pc ON safe_cast(ms.paid_date as date) = safe_cast(pc.paid_date as date) AND trim(lower(ms.market)) = trim(lower(pc.market)) and trim(lower(ms.brand)) = trim(lower(pc.brand)) where date_trunc(COALESCE(MS.paid_date, O.PAID_DATE), month) >= \'2020-01-01\' group by 1,2,3",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            